fn skip_script_comments<I>(
    script_start: TextRange,
    comments: &mut std::iter::Peekable<I>,
    locator: &Locator,
) -> bool
where
    I: Iterator<Item = TextRange>,
{
    let line_end = locator.full_line_end(script_start.end());
    let rest = locator.after(line_end);
    let mut lines = UniversalNewlineIterator::with_offset(rest, line_end);

    let mut end_offset = None;
    let mut string_state = MultilineString::None;

    while let Some(line) = lines.next() {
        let Some(content) = script_line_content(&line) else {
            break;
        };

        if content == "///" && string_state == MultilineString::None {
            end_offset = Some(line.full_end());
            break;
        }

        update_multiline_string_state(content, &mut string_state);
    }

    // > Unclosed blocks MUST be ignored.
    let Some(end_offset) = end_offset else {
        return false;
    };

    // Skip over all script-comments.
    while let Some(comment) = comments.peek() {
        if comment.start() >= end_offset {
            break;
        }
        comments.next();
    }

    true
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum MultilineString {
    None,
    Basic,
    Literal,
}

/// Updates the TOML multiline string state for a single line of script content.
///
/// This ensures that a `# ///` line that appears inside a multiline string is not
/// mistaken for the end of the script block.
fn update_multiline_string_state(content: &str, state: &mut MultilineString) {
    let bytes = content.as_bytes();
    let mut index = 0;
    while index < bytes.len() {
        match state {
            MultilineString::None => {
                if bytes[index..].starts_with(b"#") {
                    // The rest of the line is a TOML comment.
                    break;
                }
                if bytes[index..].starts_with(b"\"\"\"") {
                    *state = MultilineString::Basic;
                    index += 3;
                } else if bytes[index..].starts_with(b"'''") {
                    *state = MultilineString::Literal;
                    index += 3;
                } else {
                    index += 1;
                }
            }
            MultilineString::Basic => {
                if bytes[index] == b'\\' {
                    // Skip the escaped character.
                    index += 2;
                } else if bytes[index..].starts_with(b"\"\"\"") {
                    *state = MultilineString::None;
                    index += 3;
                } else {
                    index += 1;
                }
            }
            MultilineString::Literal => {
                if bytes[index..].starts_with(b"'''") {
                    *state = MultilineString::None;
                    index += 3;
                } else {
                    index += 1;
                }
            }
        }
    }
}

fn script_line_content(line: &str) -> Option<&str> {
    let Some(rest) = line.strip_prefix('#') else {
        // Not a comment
        return None;
    };

    // An empty line
    if rest.is_empty() {
        return Some("");
    }

    // > If there are characters after the # then the first character MUST be a space.
    rest.strip_prefix(' ')
}

